B.aXm=new A.cW("cielo_tinta",B.dG,"Cielo de tinta","Sumi-e puro. Sin color, solo grises y silencio.",B.dQ)
B.aXl=new A.cW("cielo_sangre",B.dG,"Crep\xfasculo de sangre","El cielo antes de una batalla que nadie va a librar.",B.dw)
