B.aXq=new A.cW("cielo_oro",B.dG,"Amanecer de oro","La luz que solo ven los que madrugan de verdad.",B.fB)
B.aXI=new A.cW("luna_velada",B.ep,"Luna velada","Detr\xe1s de las nubes. Est\xe1, aunque no se vea entera.",B.dQ)
B.aXg=new A.cW("luna_gemela",B.ep,"Lunas gemelas","Dos lunas. Nadie ha explicado nunca de d\xf3nde sali\xf3 la segunda.",B.f2)
