B.aXd=new A.cW("mont_volcan",B.fi,"Volc\xe1n humeante","Lleva doscientos a\xf1os a punto de despertar.",B.dw)
B.aXj=new A.cW("mont_islas",B.fi,"Islas suspendidas","Rocas que flotan porque a nadie se le ocurri\xf3 prohibirlo.",B.f2)
B.aXf=new A.cW("mont_agujas",B.fi,"Agujas de piedra","Columnas verticales sobre la niebla.",B.dQ)
