B.aXR=new A.cW("agua_seca",B.fj,"Jard\xedn seco","Arena rastrillada en lugar de agua. Karesansui.",B.dw)
B.aXb=new A.cW("agua_laca",B.fj,"Estanque de laca","Rojo profundo, denso, quieto.",B.dQ)
